import { current_batch as observer_batch } from './batch.js';

/**
 * A set of signals we have already seen while traversing in mark_reactions.

// Speculative writes must not dirty or enqueue real-world eager observers.
// Fork commit discovers and flushes them once the writes become public.
if ((flags & EAGER_EFFECT) !== 0 && observer_batch?.is_fork) continue;

var not_dirty = (flags & DIRTY) === 0;

let f;
const resolvers = [];

let a = $state(0);
let b = $state(10);
let choose_a = $state(true);
let unrelated = $state(0);
let observation_fork;
const selected = $derived(choose_a ? a : b);

$inspect(a, selected, unrelated).with((_type, ...values) => {
	console.log(`inspect ${values.join('/')}`);
});

function speculate_observations() {
	observation_fork = fork(() => {
		a = 100;
		b = 200;
		choose_a = false;
	});
}

const [speculate, update, commit, resolve, reset, observe, discard_observations, commit_observations, increment_a, increment_b, increment_unrelated] = target.querySelectorAll('button');
const observations = () => logs.filter((value) => value.startsWith('inspect '));
assert.deepEqual(observations(), ['inspect 0/0/0']);
assert.equal(target.querySelector('#observations').textContent, '0/0/0');

		}

		logs.length = 0;
		const expected = [];
		function check(value) {
			assert.deepEqual(observations(), expected);
			assert.equal(target.querySelector('#observations').textContent, value);
		}

		// Ordinary updates still notify both direct and derived observers.
		increment_a.click();
		await tick();
		expected.push('inspect 1/1/0');
		check('1/1/0');

		observe.click();
		check('1/1/0');
		// Flush unrelated eager work before the fork's queued work has settled.
		increment_unrelated.click();
		await tick();
		expected.push('inspect 1/1/1');
		check('1/1/1');
		await tick();
		check('1/1/1');

		discard_observations.click();
		check('1/1/1');
		await tick();
		check('1/1/1');
		increment_unrelated.click();
		await tick();
		expected.push('inspect 1/1/2');
		check('1/1/2');

		// Discard must retain the committed conditional dependency on a.
		increment_a.click();
		await tick();
		expected.push('inspect 2/2/2');
		check('2/2/2');

		observe.click();
		check('2/2/2');
		await tick();
		check('2/2/2');
		increment_unrelated.click();
		await tick();
		expected.push('inspect 2/2/3');
		check('2/2/3');

		commit_observations.click();
		await tick();
		await tick();
		expected.push('inspect 100/200/3');
		check('100/200/3');

		// After commit, the derived must track b rather than a.
		increment_b.click();
		await tick();
		expected.push('inspect 100/201/3');
		check('100/201/3');
		increment_a.click();
		await tick();
		expected.push('inspect 101/201/3');
		check('101/201/3');
	}
});

